function renderPhotoLab(){setRoot(hero("Архив","Неразрушающая фото-лаборатория","Оригинал всегда остаётся оригиналом. Обработанная версия создаётся отдельно в браузере.")+'<section class="v3-section photo-lab"><input id="photo-file" type="file" accept="image/*"><div class="lab-controls"><label>Контраст <input id="lab-contrast" type="range" min="50" max="180" value="110"></label><label>Яркость <input id="lab-bright" type="range" min="60" max="160" value="105"></label><button class="mini-btn" id="lab-gray">Ч/Б</button><button class="mini-btn" id="lab-sepia">Тонировать</button></div><div class="lab-grid"><div><h3>Оригинал</h3><canvas id="original-canvas"></canvas></div><div><h3>Восстановленная копия</h3><canvas id="restored-canvas"></canvas></div></div><button class="btn dark" id="save-restored">Скачать копию</button></section>');var img=new Image(),orig=$("#original-canvas"),rest=$("#restored-canvas"),ctxO=orig.getContext("2d"),ctxR=rest.getContext("2d"),gray=false,sepia=false;function draw(){if(!img.width)return;var max=1400,sc=Math.min(1,max/img.width),w=Math.round(img.width*sc),h=Math.round(img.height*sc);[orig,rest].forEach(function(c){c.width=w;c.height=h});ctxO.drawImage(img,0,0,w,h);ctxR.filter="contrast("+$("#lab-contrast").value+"%) brightness("+$("#lab-bright").value+"%)"+(gray?" grayscale(1)":"")+(sepia?" sepia(.55)":"");ctxR.drawImage(img,0,0,w,h);ctxR.filter="none"}$("#photo-file").onchange=function(e){var f=e.target.files[0];if(!f)return;var u=URL.createObjectURL(f);img.onload=function(){draw();URL.revokeObjectURL(u)};img.src=u};["lab-contrast","lab-bright"].forEach(function(id){$("#"+id).oninput=draw});$("#lab-gray").onclick=function(){gray=!gray;draw()};$("#lab-sepia").onclick=function(){sepia=!sepia;draw()};$("#save-restored").onclick=function(){var a=document.createElement("a");a.download="restored-copy.png";a.href=rest.toDataURL("image/png");a.click()}}
