async function buildSearchRows(){var x=await getPublicData(),r=[];(D.books||[]).forEach(function(a){r.push({type:"Книга",title:a[0],text:a[1]+" · "+a[2],url:"/library/",source:a[3]})});(D.dishes||[]).forEach(function(a){r.push({type:"Блюдо",title:a[0],text:a[1]+" · "+a[3],url:"/kitchen/"})});(D.dictionary||[]).forEach(function(a){r.push({type:"Джуури",title:a.lemma,text:a.ru+" · "+a.dialect,url:"/juuri/"})});(D.people||[]).forEach(function(a){r.push({type:"Личность",title:a.name,text:a.role+" · "+a.place+" · "+a.note,url:"/people/",source:a.source})});(D.traditions||[]).forEach(function(a){r.push({type:"Традиция",title:a.name,text:a.group+" · "+a.note,url:"/traditions/"})});x.content.forEach(function(a){r.push({type:a.content_type,title:a.title,text:(a.summary||"")+" "+(a.city||"")+" "+(a.category||""),url:a.source_url&&a.source_url.indexOf("/")===0?a.source_url:"/search/",source:a.source_url})});x.places.forEach(function(a){r.push({type:"Место",title:a.name,text:(a.object_type||"")+" "+(a.address||"")+" "+(a.historical_summary||""),url:"/red-sloboda/map/"})});x.media.forEach(function(a){r.push({type:"Фото/медиа",title:a.title,text:(a.caption||"")+" "+(a.year||""),url:"/archive/photos/"})});x.sources.forEach(function(a){r.push({type:"Источник",title:a.title,text:(a.publisher||"")+" "+(a.date_label||""),url:"/sources/",source:a.url})});return r}
async function renderSearch(){setRoot(hero("Музейный поиск","Найдите город, слово, песню, блюдо, книгу или документ","Поиск объединяет статические коллекции и опубликованные записи облачного архива.")+'<section class="v3-section"><div class="search-console"><input id="v3-search" autofocus placeholder="Например: Красная Слобода, Авшалумов, джуури…"><select id="v3-type"><option value="">Все типы</option></select><div id="v3-counts"></div><div id="v3-results"></div></div></section>');var rows=await buildSearchRows(),types=Array.from(new Set(rows.map(function(x){return x.type}))).sort();$("#v3-type").innerHTML+='<option>'+types.join('</option><option>')+'</option>';function go(){var q=$("#v3-search").value.trim().toLowerCase(),ty=$("#v3-type").value,h=rows.filter(function(x){return(!ty||x.type===ty)&&(!q||(x.title+" "+x.text).toLowerCase().indexOf(q)>=0)}).slice(0,150),counts={};h.forEach(function(x){counts[x.type]=(counts[x.type]||0)+1});$("#v3-counts").innerHTML=Object.keys(counts).map(function(k){return'<span class="count-chip">'+esc(k)+' · '+counts[k]+'</span>'}).join("");$("#v3-results").innerHTML=h.map(function(x){return'<a class="search-hit" href="'+esc(x.url)+'"><span class="pill">'+esc(x.type)+'</span><strong>'+esc(x.title)+'</strong><span>'+esc(x.text)+'</span></a>'}).join("")||'<p class="muted">Совпадений нет.</p>'}$("#v3-search").oninput=go;$("#v3-type").onchange=go;go()}
async function renderAssistant(){var rows=await buildSearchRows();setRoot(hero("Хранитель памяти","Спросить музей","Помощник отвечает только из опубликованной базы и показывает найденные источники. Если данных нет, он не выдумывает ответ.")+'<section class="v3-section"><div class="assistant-box"><input id="museum-question" placeholder="Почему горские евреи говорят на джуури?"><button class="btn dark" id="museum-ask">Спросить</button><div id="museum-answer"></div></div><div class="translator-box"><h2>Переводчик по подтверждённому словарю</h2><input id="juh-translate" placeholder="Введите слово на русском или джуури"><button class="mini-btn" id="juh-go">Найти перевод</button><p id="juh-result"></p><small>Если слова нет в корпусе, автоматический перевод не придумывается.</small></div></section>');$("#museum-ask").onclick=function(){var q=$("#museum-question").value.trim().toLowerCase(),terms=q.split(/\s+/).filter(function(x){return x.length>2}),scored=rows.map(function(r){var h=(r.title+" "+r.text).toLowerCase(),s=terms.reduce(function(n,t){return n+(h.indexOf(t)>=0?1:0)},0);return{r:r,s:s}}).filter(function(x){return x.s>0}).sort(function(a,b){return b.s-a.s}).slice(0,5);if(!scored.length){$("#museum-answer").innerHTML='<div class="empty-state"><strong>В архиве проекта пока нет подтверждённых данных.</strong></div>';return}$("#museum-answer").innerHTML='<h2>Найдено в музее</h2>'+scored.map(function(x){return'<article class="assistant-source"><span class="pill">'+esc(x.r.type)+'</span><h3>'+esc(x.r.title)+'</h3><p>'+esc(x.r.text)+'</p>'+(x.r.source?'<a target="_blank" rel="noopener" href="'+esc(x.r.source)+'">Источник ↗</a>':'<a href="'+esc(x.r.url)+'">Открыть материал ↗</a>')+'</article>'}).join("")};$("#juh-go").onclick=function(){var q=$("#juh-translate").value.trim().toLowerCase(),w=(D.dictionary||[]).find(function(x){return x.lemma.toLowerCase()===q||x.ru.toLowerCase()===q});$("#juh-result").textContent=w?w.lemma+" — "+w.ru+" · "+w.dialect:"В проверенном корпусе такого соответствия пока нет."}}
async function renderContribute(){setRoot(hero("Участие","Предложить материал","Фото, документ, аудио, видео, книгу, историю или исправление попадают в закрытую очередь. Автопубликации нет.")+'<section class="v3-section"><form id="cloud-contribute" class="museum-form wide"><label>Тип<select name="kind"><option>photo</option><option>document</option><option>audio</option><option>video</option><option>book</option><option>history</option><option>other</option></select></label><label>Название<input name="title" required></label><label>Описание<textarea name="description" rows="5"></textarea></label><label>Источник / происхождение<textarea name="source_note"></textarea></label><label>Контакт для уточнений<input name="contact_note"></label><label>Файл до 20 МБ<input name="file" type="file" accept="image/*,.pdf,audio/*,video/mp4"></label><label class="check"><input name="rightsBox" type="checkbox" required> Я подтверждаю право передать материал музею для проверки.</label><button class="btn dark">Передать в музей</button><p id="contribute-status"></p></form></section>');$("#cloud-contribute").onsubmit=async function(e){e.preventDefault();var fd=new FormData(e.currentTarget),status=$("#contribute-status");fd.set("rights","true");fd.delete("rightsBox");status.textContent="Сохраняю в закрытую очередь…";var r=await apiPost("contribute",fd,true);status.textContent=r&&r.ok?"Материал принят в очередь проверки.":"Не удалось принять материал: "+esc(r&&r.error||"ошибка");if(r&&r.ok)e.currentTarget.reset()}}
function renderMyths(){var a=[["Происхождение можно свести к одной простой версии","История горских евреев изучается по разным типам источников; спорные гипотезы должны быть подписаны как версии."],["Все региональные формы джуури одинаковы","Диалектные и региональные различия существуют и должны фиксироваться отдельно."],["Устное предание равно архивному документу","Устное свидетельство ценно, но музей показывает отдельный уровень достоверности."]];setRoot(hero("Исследовательский раздел","Мифы и факты","В спорных вопросах музей не выдаёт одну гипотезу за доказанный факт.")+'<section class="v3-section">'+a.map(function(x){return'<article class="myth-card"><div><span>МИФ / УПРОЩЕНИЕ</span><h2>'+esc(x[0])+'</h2></div><div><span>ЧТО МОЖНО УТВЕРЖДАТЬ</span><p>'+esc(x[1])+'</p></div></article>'}).join("")+'</section>')}
function renderGlossary(){var a=[["Джуури","Язык горских евреев; формы хранятся с источником и диалектной пометой."],["Мацева","Еврейское надгробие; эпитафии могут быть источником имён и дат."],["Мизрахи","Обобщающий термин для ряда еврейских общин Ближнего Востока и соседних регионов; контекст важен."],["Сефарды","Историко-культурная традиция, связанная прежде всего с евреями Пиренейского полуострова и их потомками."],["Ашкеназы","Историко-культурная традиция евреев Центральной и Восточной Европы."],["Хазан","Ведущий общественную молитву в синагоге."],["Синагога","Место еврейской общественной молитвы, учёбы и общинной жизни."]];setRoot(hero("Справочник","Словарь терминов","Кликабельная база терминов помогает сохранять контекст.")+'<section class="v3-section glossary-grid">'+a.map(function(x){return'<article><h2>'+x[0]+'</h2><p>'+x[1]+'</p></article>'}).join("")+'</section>')}
function renderExhibition(kiosk){var slides=[["Истоки","История народа Восточного Кавказа."],["Красная Слобода","Место, ставшее символом компактной горско-еврейской жизни."],["Джуури","Язык как живая запись памяти."],["Культура","Музыка, кухня, одежда, ремёсла и праздник."],["Архив","Фото, документы, книги, голоса и предметы."],["Сегодня","Современные общины и сохранение наследия."]],i=0;setRoot('<section class="exhibition-screen"><button id="ex-prev">←</button><div id="ex-slide"></div><button id="ex-next">→</button></section>');function show(){$("#ex-slide").innerHTML='<span>'+(i+1)+' / '+slides.length+'</span><h1>'+slides[i][0]+'</h1><p>'+slides[i][1]+'</p>'}$("#ex-prev").onclick=function(){i=(i+slides.length-1)%slides.length;show()};$("#ex-next").onclick=function(){i=(i+1)%slides.length;show()};show();if(kiosk){document.body.classList.add("kiosk-mode");var timer;function reset(){clearTimeout(timer);timer=setTimeout(function(){location.href="/"},120000)}["click","touchstart","keydown"].forEach(function(e){document.addEventListener(e,reset)});reset()}}
async function renderEvents(){var x=await getPublicData();setRoot(hero("Современная жизнь","Календарь мероприятий","Лекции, выставки, концерты, языковые встречи и памятные события публикуются только со ссылкой на источник.")+'<section class="v3-section"><div class="event-list">'+(x.events.length?x.events.map(function(e){return'<article><time>'+esc(e.starts_at?new Date(e.starts_at).toLocaleString("ru-RU"):"Дата уточняется")+'</time><div><h2>'+esc(e.title)+'</h2><p>'+esc(e.summary||"")+'</p><p>'+esc([e.city,e.venue].filter(Boolean).join(" · "))+'</p>'+(e.source_url?'<a href="'+esc(e.source_url)+'" target="_blank" rel="noopener">Источник ↗</a>':"")+'</div></article>'}).join(""):'<div class="empty-state">Опубликованных мероприятий пока нет. База готова к наполнению.</div>')+'</div></section>')}
async function renderNews(){var x=await getPublicData();setRoot(hero("О проекте","Новости проекта","Изменения базы, новые коллекции, оцифровка и исследовательские обновления.")+'<section class="v3-section"><div class="news-grid">'+x.news.map(function(n){return'<article class="v3-card"><time>'+new Date(n.published_at).toLocaleDateString("ru-RU")+'</time><h2>'+esc(n.title)+'</h2><p>'+esc(n.summary||"")+'</p>'+(n.url?'<a href="'+esc(n.url)+'">Подробнее ↗</a>':"")+'</article>'}).join("")+'</div></section>')}
function renderCommunity(){var org=D.organizations||[];setRoot(hero("Сегодня","Современная жизнь общин","Раздел связывает музей с сегодняшней культурной инфраструктурой, не выдавая организации за партнёров проекта без подтверждения.")+'<section class="v3-section museum-grid">'+org.map(function(o){return'<article class="v3-card"><span class="pill">'+esc(o.kind)+'</span><h2>'+esc(o.name)+'</h2><p>'+esc(o.note)+'</p><a href="'+esc(o.source)+'" target="_blank" rel="noopener">Источник ↗</a></article>'}).join("")+'</section>')}
function renderNewsletter(){setRoot(hero("Подписка","Новости «Нитей Памяти»","Адрес сохраняется в защищённой таблице подписчиков. Отправка писем активируется после подключения проверенного почтового домена.")+'<section class="v3-section"><form id="newsletter-form" class="museum-form compact"><label>Email<input name="email" type="email" required></label><label class="check"><input name="consent" type="checkbox" required> Согласен получать новости проекта и могу отписаться.</label><button class="btn dark">Подписаться</button><p id="newsletter-status"></p></form><p><a href="/feed.xml">RSS-лента проекта ↗</a></p></section>');$("#newsletter-form").onsubmit=async function(e){e.preventDefault();var fd=new FormData(e.currentTarget),st=$("#newsletter-status"),r=await apiPost("newsletter",{email:String(fd.get("email")).trim(),locale:prefs.lang||"ru"});st.textContent=r&&r.ok?"Подписка сохранена.":"Не удалось сохранить подписку.";if(r&&r.ok)e.currentTarget.reset()}}
function renderRoadmap(){var phases=[["Этап A · музейная основа","Навигация, PWA, поиск, источники, облачная база, Красная Слобода."],["Этап B · коллекции","Фото, книги, OCR, музыка, одежда, ремёсла, фольклор, кулинарная книга."],["Этап C · обучение","Джуури 2.0, игры, произношение, детский музей, экскурсии."],["Этап D · исследование","Модерация, научный совет, достоверность, исправления, открытые задачи."],["Этап E · открытые данные","Расширяемый публичный API и машинно-читаемые коллекции."]];setRoot(hero("О проекте","Roadmap","План развития строится от научно надёжной базы к более сложным интерактивным функциям.")+'<section class="v3-section roadmap">'+phases.map(function(x,i){return'<article><span>'+String(i+1).padStart(2,"0")+'</span><h2>'+x[0]+'</h2><p>'+x[1]+'</p></article>'}).join("")+'</section>')}
function renderThanks(){setRoot(hero("О проекте","Благодарности","Цифровой музей возможен благодаря авторам, исследователям, библиотекам, архивам, носителям языка и людям, которые сохраняют материалы.")+'<section class="v3-section museum-grid"><article class="v3-card"><h2>Исследователям языка</h2><p>Авторы словарей и учебных материалов джуури указаны рядом с языковыми данными.</p></article><article class="v3-card"><h2>Архивам и библиотекам</h2><p>Ссылки ведут к исходным каталогам и цифровым коллекциям.</p></article><article class="v3-card"><h2>Сообществу</h2><p>Новые материалы проходят проверку перед публичным появлением.</p></article></section>')}
