function renderApi(){setRoot(hero("Открытые данные","Публичный API","Первый слой открытых данных уже доступен как JSON-коллекции без личной и закрытой информации.")+'<section class="v3-section"><div class="api-doc"><code>GET /api/v1/index.json</code><code>GET /api/v1/people.json</code><code>GET /api/v1/places.json</code><p>Закрытые пользовательские данные и очередь модерации в API не входят.</p></div></section>')}
function renderPodcast(){var eps=[["01","Красная Слобода","История места и его музейные источники."],["02","Джуури","Почему язык требует записи носителей и диалектной разметки."],["03","Кухня","Блюда как документ региональной культуры."],["04","Музыка","Песни, инструменты и архивные записи."],["05","Миграции","Как рассказывать о расселении без упрощений."]];setRoot(hero("Аудио","Подкаст «Нити Памяти»","Структура подкаста готова; аудиофайлы публикуются после записи и оформления прав.")+'<section class="v3-section podcast-list">'+eps.map(function(e){return'<article><span>'+e[0]+'</span><div><h2>'+e[1]+'</h2><p>'+e[2]+'</p></div></article>'}).join("")+'</section>')}
async function renderAdmin(){var st=await apiGet("stats")||{};setRoot(hero("CMS","Музейная админка","Облачная схема, роли, модерация и очередь материалов защищены в Supabase. Публичный экран показывает только безопасную сводку.")+'<section class="v3-section"><div class="admin-stats"><div><strong>'+esc(st.places||0)+'</strong><span>Места</span></div><div><strong>'+esc(st.media||0)+'</strong><span>Медиа</span></div><div><strong>'+esc(st.content||0)+'</strong><span>Опубликованные материалы</span></div><div><strong>'+esc(st.sources||0)+'</strong><span>Источники</span></div><div><strong>'+esc(st.timeline||0)+'</strong><span>События хронологии</span></div></div><div class="notice">Очередь пользовательских материалов, исправления и операции «принять / отклонить / объединить» доступны только кураторской роли и не раскрываются публичному браузеру.</div></section>')}
function renderGenericAbout(type){var d={mission:["Миссия","Сохранить историю, язык, материальную и нематериальную культуру горских евреев в проверяемой цифровой форме."],creation:["История создания","«Нити Памяти» развивается как независимый цифровой музей: от статических экспозиций к связанной базе источников, мест, медиа и исследовательских задач."],council:["Научный совет","Раздел подготовлен под историков, лингвистов, архивистов и специалистов по Кавказу. Имена публикуются только после подтверждённого участия."]}[type];setRoot(hero("О проекте",d[0],d[1])+'<section class="v3-section"><div class="notice">Статус: '+(type==="council"?"формирование экспертного совета; участники ещё не объявлены.":"действующий принцип проекта.")+'</div></section>')}
function enhanceExisting(){var p=path,h=$(".content-hero"),html="";if(p==="/history/")html='<a href="/history/map/">Историческая карта</a><a href="/history/migrations/">Миграции</a><a href="/people/">Исторические личности</a><a href="/sources/">Источники</a>';if(p==="/red-sloboda/")html='<a href="/red-sloboda/map/">Карта</a><a href="/red-sloboda/then-now/">Тогда и сейчас</a><a href="/red-sloboda/tour/">Виртуальная прогулка</a><a href="/research/">Помогите исследованию</a>';if(p==="/juuri/")html='<a href="/juuri/learn/">Учить джуури</a><a href="/juuri/dialects/">Диалекты</a><a href="/juuri/phrasebook/">Разговорник</a><a href="/kids/">Игры</a>';if(p==="/culture/")html='<a href="/culture/clothing/">Одежда</a><a href="/culture/jewelry/">Украшения</a><a href="/culture/objects/">Предметы</a><a href="/culture/crafts/">Ремёсла</a><a href="/culture/music/">Музыка</a><a href="/culture/folklore/">Фольклор</a><a href="/culture/wedding/">Свадьба</a>';if(p==="/archive/")html='<a href="/archive/photos/">Фото</a><a href="/archive/photo-lab/">Реставрация</a><a href="/archive/videos/">Видео</a><a href="/library/ocr/">OCR книг</a><a href="/sources/">Библиография</a>';if(p==="/library/")html='<a href="/library/ocr/">OCR сканов</a><a href="/sources/">Библиография</a>';if(p==="/kitchen/")html='<a href="/culture/holiday-table/">Праздничный стол</a><a href="/contribute/">Предложить рецепт</a>';if(p==="/about/")html='<a href="/mission/">Миссия</a><a href="/creation/">История создания</a><a href="/roadmap/">Roadmap</a><a href="/thanks/">Благодарности</a><a href="/partners/">Сотрудничество</a><a href="/api/">Открытые данные</a>';if(h&&html)h.insertAdjacentHTML("afterend",'<section class="v3-shortcuts">'+html+'</section>')}
function initHome(){if(path!=="/")return;var main=$("main");if(!main||$("#weekly-museum"))return;var people=D.people||[],places=D.places||[],week=Math.floor(Date.now()/604800000),month=new Date().getMonth(),p=people.length?people[month%people.length]:null,pl=places.length?places[month%places.length]:null;var sec=document.createElement("section");sec.id="weekly-museum";sec.className="paper section";sec.innerHTML='<div class="section-head light-head"><div><span class="label teal">Музей сегодня</span><h2>Возвращайтесь за новой историей</h2></div></div><div class="weekly-grid"><article><span>Экспонат недели</span><h2>'+(D.dishes&&D.dishes.length?esc(D.dishes[week%D.dishes.length][0]):"Архивный объект")+'</h2><a href="/culture/objects/">Открыть ↗</a></article><article><span>Личность месяца</span><h2>'+esc(p?p.name:"Коллекция людей")+'</h2><a href="/people/">Открыть ↗</a></article><article><span>Город / место месяца</span><h2>'+esc(pl?pl.name:"Красная Слобода")+'</h2><a href="/red-sloboda/">Открыть ↗</a></article><article><span>Сегодня в истории</span><h2>Архив дат</h2><p>События на календарные дни добавляются после источниковой проверки.</p><a href="/calendar/">Календарь ↗</a></article></div>';var stats=$(".stats");if(stats)stats.parentNode.insertBefore(sec,stats);else main.appendChild(sec)}
var routes={"/history/map/":renderHistoryMap,"/history/migrations/":renderMigrations,"/red-sloboda/map/":renderRedMap,"/red-sloboda/then-now/":renderThenNow,"/red-sloboda/tour/":renderRedTour,"/juuri/learn/":renderLearn,"/juuri/dialects/":renderDialects,"/juuri/phrasebook/":renderPhrasebook,"/culture/clothing/":function(){renderCulture("clothing","Традиционная одежда")},"/culture/jewelry/":function(){renderCulture("jewelry","Украшения")},"/culture/objects/":function(){renderCulture("objects","Предметы быта")},"/culture/crafts/":function(){renderCulture("crafts","Ремёсла")},"/culture/music/":function(){renderCulture("music","Музыкальный архив")},"/culture/folklore/":function(){renderCulture("folklore","Фольклор")},"/culture/wedding/":renderWedding,"/culture/holiday-table/":renderHolidayTable,"/sources/":renderSources,"/research/":renderResearch,"/archive/photos/":renderPhotos,"/archive/photo-lab/":renderPhotoLab,"/archive/videos/":renderVideos,"/library/ocr/":renderOCR,"/kids/":renderKids,"/tours/":renderTours,"/assistant/":renderAssistant,"/contribute/":renderContribute,"/myths/":renderMyths,"/glossary/":renderGlossary,"/exhibition/":function(){renderExhibition(false)},"/kiosk/":function(){renderExhibition(true)},"/events/":renderEvents,"/news/":renderNews,"/community-today/":renderCommunity,"/newsletter/":renderNewsletter,"/roadmap/":renderRoadmap,"/thanks/":renderThanks,"/partners/":renderPartners,"/api/":renderApi,"/podcast/":renderPodcast,"/admin/":renderAdmin,"/search/":renderSearch,"/mission/":function(){renderGenericAbout("mission")},"/creation/":function(){renderGenericAbout("creation")},"/scientific-council/":function(){renderGenericAbout("council")}};
function applyLanguage(){document.documentElement.lang=prefs.lang==="jud"?"ru":prefs.lang;document.documentElement.dir=prefs.lang==="he"?"rtl":"ltr";nav();var sel=$("#lang-select");if(sel){sel.value=prefs.lang;sel.onchange=function(){prefs.lang=this.value;savePrefs();applyLanguage();if(routes[path])routes[path]()}}}
